#!/usr/bin/env python3
import socket, time

HOST = "127.0.0.1"
PORT = 3490

test_cases = [
    ("Only LF line endings", "GET / HTTP/1.1\nHost: example.com\n\n"),
    ("Only CR line endings", "GET / HTTP/1.1\rHost: example.com\r\r"),
    ("Mixed line endings", "GET / HTTP/1.1\r\nHost: example.com\n\n"),
    ("Missing final CRLF", "GET / HTTP/1.1\r\nHost: example.com\r\n"),
    ("Missing colon in header", "GET / HTTP/1.1\r\nHost example.com\r\n\r\n"),
    ("Space before colon", "GET / HTTP/1.1\r\nHost : example.com\r\n\r\n"),
    ("Missing HTTP version", "GET /\r\nHost: example.com\r\n\r\n"),
    ("Invalid method chars", "G@T / HTTP/1.1\r\nHost: example.com\r\n\r\n"),
    ("Absolute URI in request", "GET http://evil.com/ HTTP/1.1\r\nHost: example.com\r\n\r\n"),
    ("Duplicate Content-Length", "POST / HTTP/1.1\r\nHost: example.com\r\nContent-Length: 5\r\nContent-Length: 10\r\n\r\n12345"),
    ("Conflicting TE + CL", "POST / HTTP/1.1\r\nHost: example.com\r\nTransfer-Encoding: chunked\r\nContent-Length: 4\r\n\r\n4\r\nWiki\r\n0\r\n\r\n"),
    ("Obsolete header folding", "GET / HTTP/1.1\r\nHost: example.com\r\nX-Test: value\r\n more\r\n\r\n"),
    ("Very long header (10KB)", "GET / HTTP/1.1\r\nHost: example.com\r\nX-Long: \r\n\r\n"),
    ("Null byte in header", "GET / HTTP/1.1\r\nHost: example.com\u0000\r\n\r\n"),
    ("Invalid chunk size (hex)", "POST / HTTP/1.1\r\nHost: example.com\r\nTransfer-Encoding: chunked\r\n\r\nZ\r\nHello\r\n0\r\n\r\n"),
    ("Missing final chunk (0\\r\\n)", "POST / HTTP/1.1\r\nHost: example.com\r\nTransfer-Encoding: chunked\r\n\r\n4\r\nWiki\r\n"),
    ("Chunk size mismatch", "POST / HTTP/1.1\r\nHost: example.com\r\nTransfer-Encoding: chunked\r\n\r\n5\r\nWiki\r\n0\r\n\r\n"),
    ("CL.TE smuggling attempt", "POST / HTTP/1.1\r\nHost: example.com\r\nContent-Length: 13\r\nTransfer-Encoding: chunked\r\n\r\n0\r\n\r\nSMUGGLED"),
    ("TE.CL smuggling attempt", "POST / HTTP/1.1\r\nHost: example.com\r\nTransfer-Encoding: chunked\r\nContent-Length: 13\r\n\r\n0\r\n\r\nSMUGGLED"),
    ("Extra spaces in request line", "GET    /    HTTP/1.1\r\nHost:    example.com\r\n\r\n"),
    ("Tab in header name", "GET / HTTP/1.1\r\nHo\tst:\texample.com\r\n\r\n"),
    ("Two pipelined requests", "GET / HTTP/1.1\r\nHost:\texample.com\r\n\r\nPOST /videos HTTP/1.1\r\nHost; ffff\r\n\r\n"),
]

def classify_response(b):
    if not b: return "NO RESPONSE"
    try: text = b.decode(errors="ignore")
    except: return "INVALID RESPONSE"
    if "400" in text: return "REJECTED (400)"
    if "200" in text: return "ACCEPTED (200)"
    if "HTTP" in text: return "OTHER HTTP RESPONSE"
    return "UNKNOWN"

def run_test(name, payload):
    print(f"\n=== {name} ===")
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.settimeout(5)
            s.connect((HOST, PORT))
            s.sendall(payload.encode("utf-8", errors="surrogateescape"))
            try:
                response = s.recv(4096)
                print(f"Result: {classify_response(response)}")
                print(response.decode(errors="replace"))
            except socket.timeout:
                print("Result: TIMEOUT")
    except Exception as e:
        print(f"Result: ERROR ({e})")

if __name__ == "__main__":
    for name, payload in test_cases:
        run_test(name, payload)
        time.sleep(0.3)
    print("\n=== Done ===")
